function expandTiers(v) {
  // [max,min] 연속 압축 또는 전체 배열 → 내림차순 배열
  if (!v || !v.length) return [];
  if (v.length === 2 && v[0] > v[1] && (v[0] - v[1]) % 2 === 0 && v[0] - v[1] > 2) {
    const out = [];
    for (let t = v[0]; t >= v[1]; t -= 2) out.push(t);
    return out;
  }
  if (v.length === 2 && v[0] - v[1] === 2) return [v[0], v[1]];
  if (v.length === 2 && v[0] === v[1]) return [v[0]];
  return [...v];
}

/**
 * .def 사전 조회 — getBayOverride와 동일 형태 반환 (+ defSource 마커)
 * @param {string} shipCode 선박 약자 (예: 'KSKM')
 * @param {string|number} bayNo 베이 번호
 * @returns {object|null} { rowCount, hasZero, deckTiers, holdTiers, holdCells?, holdHasZero?, defSource: true }
 */
export function getDefBayEntry(shipCode, bayNo) {
  const ship = DEF_DICT[String(shipCode || '').trim().toUpperCase()];
  if (!ship) return null;
  const padded = String(parseInt(bayNo, 10)).padStart(2, '0');
  const e = ship.b[padded];
  if (!e) return null;
  const deckTiers = expandTiers(e.d);
  const holdTiers = expandTiers(e.t);
  const out = {
    rowCount: e.c,
    hasZero: !!e.z,
    deckTiers,
    holdTiers,
    defSource: true,
  };
  if (e.hc && holdTiers.length) out.holdCells = holdTiers.map(() => e.hc);
  if (e.hz != null) out.holdHasZero = !!e.hz;
  return out;
}
